import React, { useMemo } from 'react';
import { Bell, ChevronRight, Menu, LogOut } from 'lucide-react';
import { useLocation, Link } from 'react-router-dom';
import { findBreadcrumbPath } from './menuUtils';

interface HeaderProps {
  user: any; // From UserInfoContext
  menuData: any[];
  onToggleSidebar: () => void;
  onLogout: () => void;
}

const Header: React.FC<HeaderProps> = ({ user, menuData, onToggleSidebar, onLogout }) => {
  const { pathname } = useLocation();

  const breadcrumbs = useMemo(() => findBreadcrumbPath(menuData, pathname), [menuData, pathname]);

  return (
    <header className="bg-white border-b border-slate-200 px-4 md:px-8 py-4 sticky top-0 z-30">
      <div className="flex items-center justify-between max-w-[1600px] mx-auto">

        <div className="flex items-center gap-4">
          <button onClick={onToggleSidebar} className="md:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-lg">
            <Menu size={22} />
          </button>

          <div className="flex flex-col">
            <h1 className="text-xl md:text-2xl font-bold text-slate-800 leading-tight">
              {breadcrumbs[breadcrumbs.length - 1]?.DisplayName || "Recruitment Process"}
            </h1>

            <nav className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-slate-400 mt-0.5">
              <Link to="/" className="hover:text-blue-600 transition-colors">Home</Link>
              {breadcrumbs.map((crumb, idx) => (
                <React.Fragment key={crumb.Id}>
                  <ChevronRight size={10} strokeWidth={3} className="text-slate-300" />
                  <Link
                    to={crumb.Path}
                    className={idx === breadcrumbs.length - 1 ? "text-blue-600" : "hover:text-blue-600"}
                  >
                    {crumb.DisplayName}
                  </Link>
                </React.Fragment>
              ))}
            </nav>
          </div>
        </div>

        <div className="flex items-center gap-3 md:gap-6">
          <button className="relative p-2 text-slate-400 hover:text-blue-600 transition-colors hidden sm:block">
            <Bell size={20} />
            <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white" />
          </button>

          <div className="w-px h-8 bg-slate-200 hidden sm:block" />

          <div className="flex items-center gap-3 group">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-bold text-slate-700 leading-none">{user?.name || "Jackson"}</p>
              <p className="text-[10px] text-slate-400 uppercase font-bold mt-1">{user?.role || "HOD - Mining"}</p>
            </div>

            <div className="relative group">
              <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold border-2 border-white shadow-sm cursor-pointer">
                {user?.name?.charAt(0) || "J"}
              </div>

              <button
                onClick={onLogout}
                className="absolute -bottom-10 right-0 bg-white shadow-xl border border-slate-100 py-2 px-4 rounded-lg flex items-center gap-2 text-xs text-red-600 opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap"
              >
                <LogOut size={14} /> Logout
              </button>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;